// ---------------------------------------------------------------- tracker status journey
export function states(k) {
  const t = (en, uk) => (k === 'uk' ? uk : en);
  return {
    title: t('The life of one job in the tracker', 'Життя однієї вакансії в трекері'),
    lead: t('Press Play, or click any status to see what it means and what to do next.', 'Натисніть Play або клацніть будь-який статус, щоб побачити, що він означає і що робити далі.'),
    play: t('Play', 'Play'), pause: t('Pause', 'Пауза'),
    main: [
      { id: 'todo', l: t('Not applied', 'Не подано'), d: t('The job is in your list. Open the ad and decide: apply or skip.', 'Вакансія у вашому списку. Відкрийте оголошення й вирішіть: подаватися чи пропустити.') },
      { id: 'ready', l: t('CV ready: apply', 'Резюме готове: подати'), d: t('The package is built and passed the gate. Review it and apply yourself.', 'Пакет зібрано, бар\'єр пройдено. Перегляньте й подайтеся самі.') },
      { id: 'applied', l: t('Applied', 'Подано'), d: t('The date is recorded. The 3-day LinkedIn step starts now: find 1-2 people and write to them.', 'Дату записано. Крок LinkedIn на 3 дні починається зараз: знайдіть 1-2 людей і напишіть їм.') },
      { id: 'talk', l: t('Talk with recruiter', 'Розмова з рекрутером'), d: t('Someone replied. Prepare two short stories from your Fact Bank.', 'Хтось відповів. Підготуйте дві короткі історії з вашого Fact Bank.') },
      { id: 'screening', l: t('Screening', 'Скринінг'), d: t('A first formal check. Keep your answers close to the facts you confirmed.', 'Перша формальна перевірка. Тримайте відповіді близько до підтверджених фактів.') },
      { id: 'interview', l: t('Interview', 'Співбесіда'), d: t('Add the questions you were asked to your notes. New facts go to the Fact Bank.', 'Додайте питання, які вам ставили, у нотатки. Нові факти йдуть у Fact Bank.') },
      { id: 'offer', l: t('Offer', 'Оффер'), d: t('Compare it with your pay floor and your dealbreakers from step 3.', 'Порівняйте його з вашою мінімальною оплатою та абсолютними відмовами з кроку 3.') },
    ],
    side: [
      { id: 'rejected', l: t('Rejected', 'Відмова'), d: t('Note the reason if you got one. A rejection can still lead somewhere: a polite reply keeps the door open.', 'Запишіть причину, якщо її назвали. Відмова ще може кудись привести: ввічлива відповідь тримає двері відчиненими.') },
      { id: 'closed', l: t('Vacancy closed', 'Вакансія закрита'), d: t('The company closed the role. Nothing to do.', 'Компанія закрила роль. Нічого робити.') },
      { id: 'skip', l: t('Not a fit', 'Не підходить'), d: t('You or the screening decided to skip it. The reason stays on the card.', 'Ви або перевірка вирішили пропустити. Причина лишається на картці.') },
    ],
  };
}

// ---------------------------------------------------------------- mistakes and fixes
export function mistakes(k) {
  const t = (en, uk) => (k === 'uk' ? uk : en);
  return {
    cats: { all: t('All', 'Усе'), fact: t('Fact Bank', 'Fact Bank'), cv: t('Master CV', 'Базове резюме'), prefs: t('Preferences', 'Вподобання'), scan: t('Scanning', 'Сканування'), apply: t('Applying', 'Подача') },
    items: [
      { cat: 'fact', q: t('My facts are vague and have no numbers', 'Мої факти розмиті й без чисел'), why: t('Without a number or a clear outcome, a fact cannot support a requirement, and the ATS gate will stop.', 'Без числа чи чіткого результату факт не підтримує вимогу, і ATS-бар\'єр зупинить процес.'), fix: t('Answer the AI\'s follow-ups: how many, how long, what changed, who saw it. If no number exists, describe what changed. Never invent a number: a made-up figure fails at the first interview.', 'Відповідайте на уточнення ШІ: скільки, як довго, що змінилося, хто це бачив. Якщо числа немає, опишіть, що змінилося. Ніколи не вигадуйте число: вигадана цифра провалюється на першій співбесіді.') },
      { cat: 'fact', q: t('My CV and LinkedIn disagree (dates, titles)', 'Моє резюме і LinkedIn розходяться (дати, посади)'), why: t('Recruiters compare both. A mismatch looks careless or worse.', 'Рекрутери порівнюють обидва. Розбіжність виглядає недбало або гірше.'), fix: t('The AI flags every conflict. You choose the correct version once, and the Fact Bank keeps it. Then fix the wrong source so the mismatch is gone everywhere.', 'ШІ позначає кожен конфлікт. Ви один раз обираєте правильну версію, і Fact Bank її зберігає. Потім виправте хибне джерело, щоб розбіжності не лишилося ніде.') },
      { cat: 'fact', q: t('I shared a transcript with other people\'s names or company secrets', 'Я поділився транскриптом з іменами інших людей чи комерційними таємницями'), why: t('You may have a duty of confidentiality, and the AI does not need other people\'s data to extract your facts.', 'У вас може бути обов\'язок конфіденційності, а ШІ не потребує чужих даних, щоб витягти ваші факти.'), fix: t('Remove names, client details and confidential figures before sharing. Ask the AI to extract only what you did and achieved, and leave confidential numbers out of the Bank.', 'Приберіть імена, дані клієнтів і конфіденційні цифри перед надсиланням. Попросіть ШІ витягти лише те, що ви робили й досягли, а конфіденційні числа не додавайте у Bank.') },
      { cat: 'fact', q: t('I am not sure a fact is true or I cannot prove it', 'Я не певен, що факт правдивий, або не можу його довести'), why: t('A fact you cannot stand behind in an interview is a risk, not an asset.', 'Факт, за яким ви не можете стояти на співбесіді, це ризик, а не актив.'), fix: t('Reject it, or edit it to what you can prove. Only confirmed facts are used for CVs and messages.', 'Відхиліть його або змініть на те, що можете довести. Для резюме й повідомлень використовуються лише підтверджені факти.') },
      { cat: 'cv', q: t('The AI added a skill I do not have', 'ШІ додав навичку, якої в мене немає'), why: t('Keyword stuffing raises the match score and lowers your credibility.', 'Накачування ключовими словами піднімає оцінку збігу й знижує вашу довіру.'), fix: t('Check that every bullet shows its fact tag (F12, F07). Remove any line without one. The method never closes a gap by adding a keyword with no fact behind it.', 'Перевірте, що кожен пункт має мітку факту (F12, F07). Видаліть будь-який рядок без неї. Метод ніколи не закриває прогалину, додаючи ключове слово без факту.') },
      { cat: 'cv', q: t('The CV is too long or too generic', 'Резюме задовге або надто загальне'), why: t('Too long gets skimmed. Too generic does not match any ad well.', 'Задовге пролистують. Надто загальне погано збігається з будь-яким оголошенням.'), fix: t('Keep to 2 pages. If you search for different kinds of roles, keep one Master CV per role family and choose the right one for each job.', 'Тримайтеся 2 сторінок. Якщо шукаєте різні типи ролей, тримайте по одному базовому резюме на групу ролей і обирайте відповідне для кожної вакансії.') },
      { cat: 'cv', q: t('I used a fancy template and the ATS reads garbage', 'Я взяв ефектний шаблон, і ATS читає нісенітницю'), why: t('Columns, tables, text boxes, headers and photos break many parsers.', 'Колонки, таблиці, текстові блоки, колонтитули та фото ламають багато парсерів.'), fix: t('Use the plain structure: one column, standard headings, dates as MM/YYYY – MM/YYYY, simple bullets, .docx. Put contacts in the body, not in a page header.', 'Використовуйте просту структуру: одна колонка, стандартні заголовки, дати як MM/YYYY – MM/YYYY, прості маркери, .docx. Контакти ставте в тілі, а не в колонтитулі.') },
      { cat: 'prefs', q: t('The digest is empty', 'Дайджест порожній'), why: t('The filters are too narrow: titles, locations, or too many blockers set to wall.', 'Фільтри надто вузькі: назви, локації чи забагато блокерів з рівнем wall.'), fix: t('Run the dry run and read the skip reasons. Loosen one rule at a time and preview again. Turn some wall rules into ask so you still see the job.', 'Запустіть пробний прогін і прочитайте причини пропусків. Послаблюйте по одному правилу й дивіться знову. Частину правил wall переведіть в ask, щоб бачити вакансію.') },
      { cat: 'prefs', q: t('The digest is full of noise', 'Дайджест повний шуму'), why: t('Title keywords are too broad, or the location rules let everything in.', 'Ключові слова назв надто широкі, або правила локації пропускають усе.'), fix: t('Add off-scope words to the exclusion list (for example intern, junior, marketing). Keep P3 hidden. Narrow the title list to what you would really apply to.', 'Додайте нерелевантні слова у список винятків (наприклад intern, junior, marketing). Тримайте P3 прихованим. Звузьте список назв до тих, на які ви справді подалися б.') },
      { cat: 'prefs', q: t('A good job was skipped as a "wall"', 'Хорошу вакансію пропущено як "wall"'), why: t('A rule is stricter than you meant.', 'Правило суворіше, ніж ви мали на увазі.'), fix: t('Every skip carries a reason. Read it, find the rule, and either relax it or change it from wall to ask. Then run the preview to confirm.', 'Кожен пропуск має причину. Прочитайте її, знайдіть правило й послабте або змініть з wall на ask. Тоді запустіть перегляд для перевірки.') },
      { cat: 'prefs', q: t('I said "remote" but got jobs I cannot take', 'Я сказав "віддалено", але отримую вакансії, які не можу взяти'), why: t('"Remote" is often limited to certain countries or needs a local entity or a visa.', '"Віддалено" часто обмежено певними країнами або потребує місцевої юрособи чи візи.'), fix: t('Tell the AI where you can legally work. It adds the matching blockers and priorities (P1 to P3), and asks recruiters early about entity and visa when a role may need them.', 'Скажіть ШІ, де ви можете законно працювати. Він додасть відповідні блокери й пріоритети (P1 до P3) і рано питатиме рекрутерів про юросіб і візу, коли роль може їх потребувати.') },
      { cat: 'scan', q: t('I found a job myself. Where do I add it in the tracker?', 'Я сам знайшов вакансію. Де додати її в трекері?'), why: t('The tracker has no "add job" button on purpose. It lists jobs that came through the scan and screening.', 'У трекері навмисно немає кнопки "додати вакансію". Він показує вакансії, що пройшли сканування й перевірку.'), fix: t('Paste the job description into your AI chat to get the screening, CV and messages. To also track the job, ask the AI for a one-job import file and load it with the Import button. A direct connection (MCP) that lets the AI create the card itself is planned.', 'Вставте опис вакансії у ваш чат зі ШІ, щоб отримати перевірку, резюме й повідомлення. Щоб ще й відстежувати вакансію, попросіть ШІ підготувати файл імпорту на одну вакансію й завантажте його кнопкою імпорту. Пряме підключення (MCP), через яке ШІ сам створить картку, заплановане.') },
      { cat: 'scan', q: t('I stopped getting new jobs and see a red notice', 'Нові вакансії перестали приходити, і я бачу червоне повідомлення'), why: t('You have 20 or more cards in "Not applied". The tracker stops adding new cards until you process the existing ones.', 'У вас 20 і більше карток у статусі "Не подано". Трекер перестає додавати нові картки, доки ви не опрацюєте наявні.'), fix: t('Apply to the jobs you want, and set the rest to "Not a fit". When fewer than 20 wait, new jobs appear again at the next scan.', 'Подайтеся на вакансії, які хочете, а решті поставте "Не підходить". Коли очікує менше 20, нові вакансії знову з\'являються під час наступного сканування.') },
      { cat: 'scan', q: t('A card has no full description', 'У картці немає повного опису'), why: t('Some sources do not expose the ad text, or the page could not be read. This is rare. The card then says so.', 'Деякі джерела не віддають текст оголошення, або сторінку не вдалося прочитати. Це буває рідко. Тоді картка про це каже.'), fix: t('Open the job link, copy the ad text and paste it into your AI chat yourself. Do not let the AI guess the requirements from the title.', 'Відкрийте посилання, скопіюйте текст оголошення й вставте його у ваш чат зі ШІ самі. Не дозволяйте ШІ вгадувати вимоги за назвою.') },
      { cat: 'scan', q: t('A company shows no jobs', 'Компанія не показує вакансій'), why: t('Its career system is not supported, or the address changed.', 'Її кар\'єрна система не підтримується, або адреса змінилася.'), fix: t('Use the discovery step to find which system the company uses and to validate its endpoint. If it is not supported, paste its job ads yourself. The rest of the chain works the same.', 'Скористайтеся кроком виявлення, щоб знайти, яку систему вживає компанія, і перевірити адресу. Якщо вона не підтримується, вставляйте оголошення самі. Решта ланцюжка працює так само.') },
      { cat: 'scan', q: t('The same job appears twice', 'Та сама вакансія з\'являється двічі'), why: t('It is posted on several boards or in several countries.', 'Її опубліковано на кількох сайтах чи в кількох країнах.'), fix: t('The engine matches by link, job id, and company with a similar role, and collapses one posting per country into one row. Different roles are never merged. If a true duplicate slips through, mark one as Not a fit.', 'Рушій порівнює за посиланням, id вакансії та компанією з подібною роллю, а публікації по країнах зводить в один рядок. Різні ролі ніколи не зливаються. Якщо справжній дублікат прослизнув, позначте одну як "Не підходить".') },
      { cat: 'scan', q: t('The digest email does not arrive', 'Лист-дайджест не надходить'), why: t('Mail settings are missing or wrong, or the message went to spam.', 'Налаштування пошти відсутні чи хибні, або лист потрапив у спам.'), fix: t('Use an app password, not your normal password. Send a test email from the last report. Check spam. The scan itself still writes the report even when email fails.', 'Використовуйте пароль додатка, а не звичайний пароль. Надішліть тестовий лист з останнього звіту. Перевірте спам. Сканування все одно записує звіт, навіть коли лист не надіслався.') },
      { cat: 'apply', q: t('The gate stops: "match below target"', 'Бар\'єр зупиняє: "збіг нижче цілі"'), why: t('Real facts do not cover enough of the requirements.', 'Реальні факти не покривають достатньо вимог.'), fix: t('Read the named gaps. If you have a true fact the Bank is missing, add it and run again. If not, skip the job or apply knowing the gap. Never add a keyword you cannot back up.', 'Прочитайте названі прогалини. Якщо у вас є правдивий факт, якого бракує в Bank, додайте його й запустіть знову. Якщо ні, пропустіть вакансію або подавайтеся, знаючи про прогалину. Ніколи не додавайте ключове слово, яке не можете підтвердити.') },
      { cat: 'apply', q: t('I applied with the same CV everywhere', 'Я подавався скрізь з одним резюме'), why: t('A Master CV works, but an adjusted CV matches the ad better and shows effort.', 'Базове резюме працює, але адаптоване краще збігається з оголошенням і показує зусилля.'), fix: t('For jobs you really want, run the full step 4 and use the tailored package. Use the Master CV as it is only when speed matters more than fit.', 'Для вакансій, які справді хочете, пройдіть увесь крок 4 і використайте адаптований пакет. Базове резюме як є використовуйте, лише коли швидкість важливіша за відповідність.') },
      { cat: 'apply', q: t('I applied twice to the same company within a month', 'Я двічі подався в ту саму компанію за місяць'), why: t('A second application close to the first usually gets fewer replies.', 'Друга подача поруч із першою зазвичай отримує менше відповідей.'), fix: t('The full tracker warns you and shows the earlier application. Apply again only if the new role fits clearly better, or write to the recruiter you already talked to.', 'Повний трекер попереджає й показує попередню подачу. Подавайтеся знову, лише якщо нова роль явно краще підходить, або напишіть рекрутеру, з яким уже говорили.') },
      { cat: 'apply', q: t('I applied and heard nothing', 'Я подався і не почув нічого'), why: t('Applications through job sites rarely get replies on their own.', 'Подачі через сайти з вакансіями рідко отримують відповідь самі по собі.'), fix: t('Within 3 days of applying, find 1-2 people at the company (recruiter, hiring manager) and send the drafted message. After about a month of silence, send one short follow-up.', 'Протягом 3 днів після подачі знайдіть 1-2 людей у компанії (рекрутер, керівник найму) й надішліть підготовлене повідомлення. Після приблизно місяця тиші надішліть одне коротке нагадування.') },
      { cat: 'apply', q: t('My cover message is too long', 'Мій супровідний лист задовгий'), why: t('Many forms cut text at 1000 characters.', 'Багато форм обрізають текст на 1000 символах.'), fix: t('The counter turns red above 1000. Ask the AI to shorten it. Keep five parts: greeting, why you want to join, what you bring, an invitation, closing and name.', 'Лічильник червоніє після 1000. Попросіть ШІ скоротити. Збережіть п\'ять частин: вітання, чому хочете приєднатися, що приносите, запрошення, завершення з іменем.') },
    ],
  };
}
